package com.nexamart.backend.domain;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="users",indexes={@Index(name="idx_users_email",columnList="email",unique=true),@Index(name="idx_users_username",columnList="username",unique=true)})
public class UserAccount{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String name;@Column(unique=true)private String username;@Column(unique=true)private String email;private String phone;@Column(nullable=false)private String passwordHash;@Enumerated(EnumType.STRING)@Column(nullable=false)private Role role;@Enumerated(EnumType.STRING)@Column(nullable=false)private AccountStatus status=AccountStatus.ACTIVE;private Instant createdAt=Instant.now();private Instant lastActiveAt;
 @Column(name="deleted_at")private Instant deletedAt;
 public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public Role getRole(){return role;} public void setRole(Role v){role=v;} public AccountStatus getStatus(){return status;} public void setStatus(AccountStatus v){status=v;} public Instant getCreatedAt(){return createdAt;} public Instant getLastActiveAt(){return lastActiveAt;} public void setLastActiveAt(Instant v){lastActiveAt=v;} public Instant getDeletedAt(){return deletedAt;} public void setDeletedAt(Instant v){deletedAt=v;}}
